import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CcJ8wlZS.js";const m=JSON.parse('{"title":"Why not just a wiki, notes app, or RAG?","description":"Failure modes of alternatives and the core bet","frontmatter":{"type":"index","title":"Why not just a wiki, notes app, or RAG?","description":"Failure modes of alternatives and the core bet","created":"2026-09-19T00:00:00.000Z","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"why.md","filePath":"why.md"}'),r={name:"why.md"};function i(n,e,c,d,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="why-not-just-a-wiki-notes-app-or-rag" tabindex="-1">Why Not Just a Wiki, Notes App, or RAG? <a class="header-anchor" href="#why-not-just-a-wiki-notes-app-or-rag" aria-label="Permalink to &quot;Why Not Just a Wiki, Notes App, or RAG?&quot;">​</a></h1><p>Most knowledge systems fail agents (and humans) in the same ways. Wiki Fabric is designed against those failure modes — and, critically, the governance claims are <strong>executable</strong>: lint enforces them (<code>SCOPE</code>, <code>REVIEW-AFTER</code>, <code>SYNC-CONFLICT</code>, <code>SOURCE-DRIFT</code>), CI proves them, and behavior evals measure delivery.</p><table tabindex="0"><thead><tr><th>Common system</th><th>Failure mode</th><th>Wiki Fabric&#39;s answer</th></tr></thead><tbody><tr><td><strong>Wiki / notes app</strong> (Obsidian, Notion, Confluence)</td><td>Pages drift from reality; nothing enforces freshness or provenance; orphaned pages rot silently</td><td>Every claim carries a <code>last_verified</code> date, a source locator, and a verbatim quote. A deterministic linter (14 checks) fails loudly on broken links, orphans, hash drift, and unsupported claims</td></tr><tr><td><strong>RAG / vector DB</strong></td><td>Retrieval is opaque; answers cite nothing auditable; stale chunks silently poison results; every question costs tokens</td><td>Retrieval is deterministic (lexical + graph expansion, 0 tokens). Answers are structured (<code>bottom line / evidence / caveats / confidence</code>) and every evidence item links to a line-level locator you can open and verify</td></tr><tr><td><strong>Memory tools</strong> (session memory, auto-summaries)</td><td>Unstructured prose; contradicts itself over time; no way to tell &quot;measured&quot; from &quot;guessed&quot;</td><td>Claims are atomic and typed: <code>supported</code>, <code>contested</code>, <code>superseded</code>. Contradictions are represented, not collapsed. Confidence and evidence strength are explicit fields, not vibes</td></tr><tr><td><strong>ADR collections</strong></td><td>Decisions recorded but never revisited; no feedback loop from outcomes</td><td>Decisions connect to experience events (what actually happened), which cluster into patterns with measured maturity. A pattern read but never applied gets flagged</td></tr><tr><td><strong>Prompt/skill libraries</strong></td><td>Copied between projects by hand; drift apart; no evidence of what works</td><td>Skills and patterns live in one global fabric. Promotion requires replication in ≥2 independent projects. Projects inherit them automatically at session start</td></tr><tr><td><strong>Second-brain tools</strong></td><td>Capture is cheap, retrieval and trust are expensive; nothing compounds</td><td>Structure from day one: capture → claim → concept → pattern. Each layer is machine-checkable, so the fabric stays queryable as it grows to thousands of pages</td></tr></tbody></table><p>The core bet: <strong>an LLM is a good compiler but a unreliable memory.</strong> So the fabric stores structured, source-anchored claims (not prose summaries), does all retrieval deterministically, and spends LLM tokens only where judgment is needed — extraction and synthesis. You review at defined gates; the machine handles the bookkeeping.</p><hr><h2 id="what-is-this" tabindex="-1">What Is This? <a class="header-anchor" href="#what-is-this" aria-label="Permalink to &quot;What Is This?&quot;">​</a></h2><p>Wiki Fabric is a governance layer and reference implementation for coding-agent memory. Four properties, each machine-enforced:</p><ol><li><strong>Compiles raw sources into verified claims</strong> — LLM extracts atomic assertions with line-level locators and verbatim quotes. Provenance is mandatory (lint: claims without sources can&#39;t become canonical).</li><li><strong>Promotes cross-project patterns with measured maturity</strong> — experience events are deterministically clustered into promotion dossiers; promotion requires ≥2 independent projects and human review.</li><li><strong>Enforces scope precedence at task time</strong> — <code>wf context</code> compiles project decisions &gt; domain patterns &gt; global policies into a manifest where every inclusion/exclusion carries a reason, and stale/superseded knowledge is filtered before it can mislead.</li><li><strong>Measures behavior, not vibes</strong> — behavior evals verify the knowledge actually changes agent decisions (avoids banned approaches, honors constraints, escalates gaps); the compiler has its own golden-corpus eval; CI fails on regression.</li></ol><p>Everything else — the <code>wf</code> CLI, uv installer, Obsidian vault, git-history capture, corpus sync — is reference implementation and integrations around that core.</p><hr><h2 id="what-is-this-1" tabindex="-1">What Is This? <a class="header-anchor" href="#what-is-this-1" aria-label="Permalink to &quot;What Is This?&quot;">​</a></h2><p>Wiki Fabric is a governance layer and reference implementation for coding-agent memory. Four properties, each machine-enforced:</p><ol><li><strong>Compiles raw sources into verified claims</strong> — LLM extracts atomic assertions with line-level locators and verbatim quotes. Provenance is mandatory (lint: claims without sources can&#39;t become canonical).</li><li><strong>Promotes cross-project patterns with measured maturity</strong> — experience events are deterministically clustered into promotion dossiers; promotion requires ≥2 independent projects and human review.</li><li><strong>Enforces scope precedence at task time</strong> — <code>wf context</code> compiles project decisions &gt; domain patterns &gt; global policies into a manifest where every inclusion/exclusion carries a reason, and stale/superseded knowledge is filtered before it can mislead.</li><li><strong>Measures behavior, not vibes</strong> — behavior evals verify the knowledge actually changes agent decisions (avoids banned approaches, honors constraints, escalates gaps); the compiler has its own golden-corpus eval; CI fails on regression.</li></ol><p>Everything else — the <code>wf</code> CLI, uv installer, Obsidian vault, git-history capture, corpus sync — is reference implementation and integrations around that core.</p><hr>',15)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
